// ── Structured logging with pino + correlation ID middleware ─────
import pino from 'pino';
import { randomUUID } from 'crypto';
import express from 'express';

// Base logger: JSON in production, pretty-printed in development.
// The LOG_LEVEL env var controls verbosity at deploy time.
const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  base: { service: 'order-service', version: process.env.APP_VERSION ?? 'unknown' },
  // Redact sensitive fields from every log record:
  redact: ['req.headers.authorization', 'body.password', 'body.cardNumber'],
});

const app = express();
app.use(express.json());

// ── Middleware 1: Correlation ID ──────────────────────────────────
// Generate a new ID at the entry point, or propagate one from upstream.
// The W3C traceparent header is preferred; fall back to x-correlation-id.
app.use((req, res, next) => {
  const correlationId =
    req.headers['x-correlation-id'] ??
    extractTraceIdFromTraceparent(req.headers['traceparent']) ??
    randomUUID();

  // Echo the correlation ID back to the client for support use.
  res.setHeader('x-correlation-id', correlationId);

  // Bind the ID to a child logger — every req.log.* call includes it.
  req.log = logger.child({
    correlationId,
    path: req.path,
    method: req.method,
  });

  next();
});

// ── Middleware 2: Request lifecycle logging ───────────────────────
app.use((req, res, next) => {
  const startMs = Date.now();
  req.log.info({ event: 'request.start' });

  res.on('finish', () => {
    const durationMs = Date.now() - startMs;
    // Choose log level based on HTTP status:
    const level =
      res.statusCode >= 500 ? 'error' :
      res.statusCode >= 400 ? 'warn'  : 'info';

    req.log[level]({
      event: 'request.end',
      statusCode: res.statusCode,
      durationMs,
    });
  });

  next();
});

// ── Route: Create order ───────────────────────────────────────────
app.post('/orders', async (req, res) => {
  const { userId, items } = req.body;

  try {
    req.log.debug({ userId, itemCount: items.length }, 'Validating order');

    const order = await orderService.create(userId, items);

    req.log.info({
      event: 'order.created',
      orderId: order.id,
      userId,
      total: order.total,
    });

    res.status(201).json(order);
  } catch (err) {
    req.log.error({
      event: 'order.failed',
      userId,
      err: { message: err.message, code: err.code },
    });
    res.status(500).json({ error: 'Order creation failed', correlationId: req.headers['x-correlation-id'] });
  }
});

// ── Propagating correlation ID to downstream service calls ────────
async function callPaymentService(correlationId, traceparent, payload) {
  return fetch('http://payment-service/charge', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-correlation-id': correlationId,
      // W3C Trace Context — OTel SDK can inject this automatically:
      'traceparent': traceparent,
    },
    body: JSON.stringify(payload),
  });
}

function extractTraceIdFromTraceparent(header) {
  // Format: 00-{traceId}-{parentSpanId}-{flags}
  if (!header) return null;
  const parts = header.split('-');
  return parts.length >= 2 ? parts[1] : null;
}

console.log('Order service: structured logging + correlation IDs active');

// ── OpenTelemetry setup and manual span instrumentation ──────────
// File: otel.js — load with node --require ./otel.js before all imports.
import { NodeSDK } from '@opentelemetry/sdk-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc';
import { Resource } from '@opentelemetry/resources';
import { SEMRESATTRS_SERVICE_NAME, SEMRESATTRS_SERVICE_VERSION } from '@opentelemetry/semantic-conventions';
import { SimpleSpanProcessor, BatchSpanProcessor } from '@opentelemetry/sdk-trace-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { TraceIdRatioBasedSampler } from '@opentelemetry/sdk-trace-base';

const sdk = new NodeSDK({
  // Resource: metadata about THIS service, attached to every span.
  resource: new Resource({
    [SEMRESATTRS_SERVICE_NAME]: 'order-service',
    [SEMRESATTRS_SERVICE_VERSION]: process.env.APP_VERSION ?? '0.0.0',
    'deployment.environment': process.env.NODE_ENV ?? 'development',
  }),

  // Exporter: send spans to the OTel Collector via gRPC.
  // In production, use BatchSpanProcessor (buffers + batches).
  // In development, use SimpleSpanProcessor (immediate, no buffering).
  spanProcessor: new BatchSpanProcessor(
    new OTLPTraceExporter({ url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? 'http://localhost:4317' })
  ),

  // Sampler: record 10% of traces in production.
  // In development, sample 100% to see everything.
  sampler: new TraceIdRatioBasedSampler(
    process.env.NODE_ENV === 'production' ? 0.1 : 1.0
  ),

  // Auto-instrumentation: automatically creates spans for
  // Express routes, HTTP client calls (fetch, axios), pg, redis, etc.
  instrumentations: [getNodeAutoInstrumentations()],
});

sdk.start();
process.on('SIGTERM', () => sdk.shutdown());

// ── Manual span creation in business logic ────────────────────────
import { trace, SpanStatusCode, context, propagation } from '@opentelemetry/api';

const tracer = trace.getTracer('order-service', '1.0.0');

async function processOrder(userId, items) {
  // startActiveSpan creates a span as a child of any active span
  // (set by the auto-instrumented Express middleware).
  return tracer.startActiveSpan('processOrder', async (span) => {
    try {
      // Attributes: indexed, queryable key-value pairs on the span.
      span.setAttributes({
        'user.id': userId,
        'order.item_count': items.length,
        'order.total_usd': calculateTotal(items),
      });

      const inventoryResult = await checkInventory(items);
      // Events: timestamped log-like entries attached to the span.
      span.addEvent('inventory.checked', { allAvailable: inventoryResult.allAvailable });

      if (!inventoryResult.allAvailable) {
        // Record a business-logic error, but do not throw — not a system error.
        span.addEvent('inventory.insufficient', { missingItems: inventoryResult.missing });
        return { success: false, reason: 'insufficient_inventory' };
      }

      const payment = await chargeCard(userId, calculateTotal(items));
      span.addEvent('payment.completed', { paymentId: payment.id });

      const order = await saveOrder(userId, items, payment.id);
      span.setAttribute('order.id', order.id);
      span.setStatus({ code: SpanStatusCode.OK });

      return { success: true, order };
    } catch (err) {
      // recordException captures the stack trace on the span.
      span.recordException(err);
      span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
      throw err;
    } finally {
      // Always end the span, even if an exception is thrown.
      span.end();
    }
  });
}

// ── Propagating trace context in outbound HTTP calls ──────────────
// With auto-instrumentation, fetch/axios calls automatically inject
// the traceparent header. For manual fetch:
async function callInventoryService(items) {
  const headers = {};
  // OTel propagation API injects traceparent + tracestate:
  propagation.inject(context.active(), headers);

  return fetch('http://inventory-service/check', {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...headers },
    body: JSON.stringify({ items }),
  });
}

console.log('OTel SDK initialised: spans + auto-instrumentation active');
